# Surah Al-Ma'ida (chapter 5) — part 11: ayat 101-110 (IDs 770-779)
SURAH = 5

ENTRIES = {
770: (
"اے ایمان والو! وہ چیزوں کے بارے میں مت پوچھو — جو اگر تمہیں ظاہر ہو جائیں تو تمہیں بری لگیں — اور اگر تم — قرآن کے نازل ہونے کے وقت — ان کے بارے میں پوچھو تو وہ تمہیں ظاہر کر دی جائیں — اللہ — ان — سے — معاف کرتا ہے — اور اللہ بخشش والا — بردبار — ہے",
"""۱۔ فضول سوالات — نہ پوچھو۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِن تُبْدَ لَكُمْ تَسُؤْكُمْ‘‘ — اے ایمان والو! وہ چیزوں کے بارے میں مت پوچھو — جو اگر تمہیں ظاہر ہو جائیں تو تمہیں بری لگیں — یعنی فضول سوالات — جواب ناپسندیدہ ہو سکتا ہے۔
۳۔ ’’وَإِن تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ‘‘ — اور اگر تم — قرآن کے نازل ہونے کے وقت — ان کے بارے میں پوچھو تو وہ تمہیں ظاہر کر دی جائیں — یعنی جو سوال واقعی کرنا ہو — وہ پوچھ سکتے ہو۔
۴۔ ’’عَفَا اللّٰہُ عَنْهَا وَاللّٰہُ غَفُورٌ حَلِيمٌ‘‘ — اللہ — ان — سے — معاف کرتا ہے — اور اللہ بخشش والا — بردبار — ہے۔
۵۔ عملی سبق: فضول سوالات مت پوچھو؛ کام کی بات پوچھو۔"""
),
771: (
"یہی قسم کے سوالات تم سے پہلے ایک قوم نے پوچھے — پھر انہی کی وجہ سے کافر ہو گئے",
"""۱۔ پچھلی امتوں کے فضول سوالات — کفر پر منتج ہوئے۔
۲۔ ’’قَدْ سَأَلَهَا قَوْمٌ مِّن قَبْلِكُمْ ثُمَّ أَصْبَحُوا بِهَا كَافِرِينَ‘‘ — یہی قسم کے سوالات تم سے پہلے ایک قوم نے پوچھے — پھر انہی کی وجہ سے کافر ہو گئے — یعنی بنی اسرائیل نے فضول سوالات کیے اور ایمان چھوٹ گئے۔
۳۔ عملی سبق: فضول سوالات سے بچو؛ ایمان محفوظ رکھو۔"""
),
772: (
"اللہ نے — بحیرہ — سائلہ — وصیلہ — اور حام — میں سے — کچھ نہیں بنایا — لیکن — کافر لوگ — اللہ پر جھوٹ گھڑتے ہیں — اور ان میں سے اکثر نہیں جانتے",
"""۱۔ بحیرہ وغیرہ — اللہ کے حرام کردہ نہیں۔
۲۔ ’’مَّا جَعَلَ اللّٰہُ مِن بَحِيرَۃٍ وَلَا سَائِبَۃٍ وَلَا وَصِيلَۃٍ وَلَا حَامٍ‘‘ — اللہ نے — بحیرہ — سائلہ — وصیلہ — اور حام — میں سے — کچھ نہیں بنایا — یعنی جاہلیت کے یہ جانور — خود ساختہ رسوم تھے — اللہ نے نہیں بنائے۔
۳۔ ’’وَلَٰكِنَّ الَّذِينَ كَفَرُوا يَفْتَرُونَ عَلَى اللّٰہِ الْكَذِبَ‘‘ — لیکن — کافر لوگ — اللہ پر جھوٹ گھڑتے ہیں — یعنی یہ رسم — ان کی گھڑت ہے۔
۴۔ ’’وَأَكْثَرُهُمْ لَا يَعْقِلُونَ‘‘ — اور ان میں سے اکثر نہیں جانتے — یعنی بغیر سمجھے وہ تقلید کرتے ہیں۔
۵۔ عملی سبق: اللہ کی حلال کردہ چیزوں کو حرام مت سمجھو؛ خود ساختہ رسوم سے بچو۔"""
),
773: (
"اور جب ان سے کہا جاتا ہے کہ — جو اللہ نے نازل کیا — اور رسول کی طرف آؤ — تو وہ کہتے ہیں: جو ہم نے اپنے باپ دادا کو پاتا — وہی ہمارے لیے کافی ہے — کیا — اگرچہ — ان کے باپ دادا نہ جانتے हों کچھ بھی — اور نہ ہدایت پائیں",
"""۱۔ آباء کی غلطی کی تقلید — باطل۔
۲۔ ’’وَإِذَا قِيلَ لَهُمْ تَعَالَوْا إِلَىٰ مَا أَنزَلَ اللّٰہُ وَإِلَى الرَّسُولِ قَالُوا حَسْبُنَا مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا‘‘ — اور جب ان سے کہا جاتا ہے کہ — جو اللہ نے نازل کیا — اور رسول کی طرف آؤ — تو وہ کہتے ہیں: جو ہم نے اپنے باپ دادا کو پاتا — وہی ہمارے لیے کافی ہے — یعنی آباء کی غلطی کی پیروی۔
۳۔ ’’أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْلَمُونَ شَيْئًا وَلَا يَهْتَدُونَ‘‘ — کیا — اگرچہ — ان کے باپ دادا نہ جانتے हों کچھ بھی — اور نہ ہدایت پائیں — یعنی آباء کی لاعلمی بھی معقول دلیل نہیں۔
۴۔ عملی سبق: آباء کی غلطی کی تقلید مت کرو؛ حق کو پہچان کر اختیار کرو۔"""
),
774: (
"اے ایمان والو! تم اپنے اوپر — ہی — واجب ہو — جو گمراہ ہوا — وہ تمہیں — کچھ — نقصان نہیں دے گا — جب تم ہدایت پا چکے — سب کی واپسی اللہ کی طرف ہے — پس وہ تمہیں — بتائے گا جو تم کرتے تھے",
"""۱۔ اپنی ہدایت کی فکر کرو — دوسروں کی گمراہی نقصان دہ نہیں۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا عَلَيْكُمْ أَنفُسَكُمْ لَا يَضُرُّكُم مَّن ضَلَّ إِذَا اهْتَدَيْتُمْ‘‘ — اے ایمان والو! تم اپنے اوپر — ہی — واجب ہو — جو گمراہ ہوا — وہ تمہیں — کچھ — نقصان نہیں دے گا — جب تم ہدایت پا چکے — یعنی اپنی ہدایت کی فکر کرو — دوسروں سے مت ڈرو۔
۳۔ ’’إِلَى اللّٰہِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ‘‘ — سب کی واپسی اللہ کی طرف ہے — پس وہ تمہیں — بتائے گا جو تم کرتے تھے۔
۴۔ عملی سبق: اپنی ہدایت کی فکر کرو؛ نیکی کی دعوت دو؛ مایوسی مت کرو۔"""
),
775: (
"اے ایمان والو! تمہارے درمیان گواہی — جب تم میں سے کسی کو موت — وصیت کے وقت — آئے — دو — عدل والے — تمہارے ہی — میں سے — یا — دوسروں — میں سے — جب تم زمین میں سفر کر رہے ہو — اور تمہیں موت کا سانحہ پہنچ جائے — تو تم دونوں کو نماز کے بعد روک لو — ان دونوں سے — قسم لو — اگر تمہیں شک ہے — (کہ) ہم کسی قیمت کے بدلے (گواہی) نہیں بیچیں گے — اگرچہ وہ قریب کا رشتہ دار کیوں نہ ہو — اور اللہ کی گواہی — ہم — نہیں چھپائیں گے — ہم — اس وقت — ضرور گنہگار — ہوں گے",
"""۱۔ وصیت کی گواہی — دو عدل والے گواہ۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَۃُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّۃِ اثْنَانِ ذَوَا عَدْلٍ مِّنكُمْ‘‘ — اے ایمان والو! تمہارے درمیان گواہی — جب تم میں سے کسی کو موت — وصیت کے وقت — آئے — دو — عدل والے — تمہارے ہی — میں سے — یعنی وصیت کے وقت دو عادل گواہ ہوں۔
۳۔ ’’أَوْ آخَرَانِ مِنْ غَيْرِكُمْ إِنْ أَنتُمْ ضَرَبْتُمْ فِي الْأَرْضِ فَأَصَابَتْكُم مُّصِيبَۃُ الْمَوْتِ‘‘ — یا — دوسروں — میں سے — جب تم زمین میں سفر کر رہے ہو — اور تمہیں موت کا سانحہ پہنچ جائے — یعنی سفر میں غیر مسلم بھی گواہ بن سکتے ہیں۔
۴۔ ’’تَحْبِسُونَهُمَا مِن بَعْدِ الصَّلَاةِ فَيُقْسِمَانِ بِاللّٰہِ إِنِ ارْتَبْتُمْ لَا نَشْتَرِي بِهِ ثَمَنًا وَلَوْ كَانَ ذَا قُرْبَىٰ‘‘ — تو تم دونوں کو نماز کے بعد روک لو — ان دونوں سے — قسم لو — اگر تمہیں شک ہے — (کہ) ہم کسی قیمت کے بدلے (گواہی) نہیں بیچیں گے — اگرچہ وہ قریب کا رشتہ دار کیوں نہ ہو — یعنی گواہی — بڑی قیمت کے باوجود سچی ہو۔
۵۔ ’’وَلَا نَكْتُمُ شَهَادَۃَ اللّٰہِ إِنَّا إِذًا لَّمِنَ الْآثِمِينَ‘‘ — اور اللہ کی گواہی — ہم — نہیں چھپائیں گے — ہم — اس وقت — ضرور گنہگار — ہوں گے۔
۶۔ عملی سبق: عادل گواہ بنو؛ گواہی نہ چھپاؤ؛ رشوت سے بچو۔"""
),
776: (
"پھر اگر — یہ ثابت ہو کہ — دونوں گواہ گناہ کے مستحق — ہو گئے — تو — دو — ان لوگوں میں سے — جن (مرے ہوئے) پر حق ہے — اس کے حق دار — کچھ اور — دوسرے — کھڑے ہوں — قسم اٹھائیں — اللہ کی — (کہ) ہم (دوسرے) کی گواہی — ان دونوں کی گواہی سے — زیادہ سچی ہے — اور ہم حد سے نہیں بڑھے — ہم — اس وقت — ضرور ظالموں میں — سے — ہوں گے",
"""۱۔ گواہوں کے جھوٹ ثابت ہونے پر — دوسرے دو گواہ۔
۲۔ ’’فَإِنْ عُثِرَ عَلَىٰ أَنَّهُمَا اسْتَحَقَّا إِثْمًا فَآخَرَانِ يَقُومَانِ مَقَامَهُمَا مِنَ الَّذِينَ اسْتَحَقَّ عَلَيْهِمُ الْأَوْلَيَانِ‘‘ — پھر اگر — یہ ثابت ہو کہ — دونوں گواہ گناہ کے مستحق — ہو گئے — تو — دو — ان لوگوں میں سے — جن (مرے ہوئے) پر حق ہے — اس کے حق دار — کچھ اور — دوسرے — کھڑے ہوں — یعنی جھوٹے گواہوں کے بعد دوسرے گواہ کھڑے ہوں۔
۳۔ ’’فَيُقْسِمَانِ بِاللّٰہِ لَشَهَادَتُنَا أَحَقُّ مِن شَهَادَتِهِمَا وَمَا اعْتَدَيْنَا إِنَّا إِذًا لَّمِنَ الظَّالِمِينَ‘‘ — قسم اٹھائیں — اللہ کی — (کہ) ہم (دوسرے) کی گواہی — ان دونوں کی گواہی سے — زیادہ سچی ہے — اور ہم حد سے نہیں بڑھے — ہم — اس وقت — ضرور ظالموں میں — سے — ہوں گے۔
۴۔ عملی سبق: گواہی سچی بنو؛ اللہ کا خوف رکھو۔"""
),
777: (
"یہ — اس کے — زیادہ قریب ہے کہ — وہ (گواہ) — گواہی — اس کے اصل — پر — لائیں — یا ڈر جائیں — کہ — ان کی قسموں کے بعد — قسمیں واپس کی جائیں — اور اللہ سے ڈرو — اور سنو — اور اللہ نافرمان — لوگوں کو ہدایت نہیں دیتا",
"""۱۔ سچی گواہی کی حوصلہ افزائی — اور جھوٹ کی سزا۔
۲۔ ’’ذَٰلِكَ أَدْنَىٰ أَن يَأْتُوا بِالشَّهَادَۃِ عَلَىٰ وَجْهِهَا أَوْ يَخَافُوا أَن تُرَدَّ أَيْمَانٌ بَعْدَ أَيْمَانِهِمْ‘‘ — یہ — اس کے — زیادہ قریب ہے کہ — وہ (گواہ) — گواہی — اس کے اصل — پر — لائیں — یا ڈر جائیں — کہ — ان کی قسموں کے بعد — قسمیں واپس کی جائیں — یعنی جھوٹے گواہوں کے متبادل گواہ کھڑے ہونے کا امکان — جھوٹے گواہوں کو محتاط رکھتا ہے۔
۳۔ ’’وَاتَّقُوا اللّٰہَ وَاسْمَعُوا وَاللّٰہُ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ‘‘ — اور اللہ سے ڈرو — اور سنو — اور اللہ نافرمان — لوگوں کو ہدایت نہیں دیتا۔
۴۔ عملی سبق: سچی گواہی دو؛ اللہ کا خوف کرو۔"""
),
778: (
"جس دن اللہ — رسولوں کو جمع کرے گا — پھر ان سے پوچھے گا — تمہیں کیا جواب دیا گیا — وہ کہیں گے — ہمیں کوئی علم نہیں — بے شک آپ ہی — غیبوں کے جاننے والے ہیں",
"""۱۔ قیامت کا دن — رسولوں سے سوالات۔
۲۔ ’’يَوْمَ يَجْمَعُ اللّٰہُ الرُّسُلَ فَيَقُولُ مَاذَا أُجِبْتُمْ‘‘ — جس دن اللہ — رسولوں کو جمع کرے گا — پھر ان سے پوچھے گا — تمہیں کیا جواب دیا گیا — یعنی قیامت کے دن — رسولوں سے ان کی امتوں کے بارے میں سوال ہوگا۔
۳۔ ’’قَالُوا لَا عِلْمَ لَنَا إِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ‘‘ — وہ کہیں گے — ہمیں کوئی علم نہیں — بے شک آپ ہی — غیبوں کے جاننے والے ہیں — یعنی رسول — ادب و احترام سے — اللہ کی طرف رجوع کریں گے۔
۴۔ عملی سبق: رسولوں کا احترام کرو؛ اللہ ہی سب کچھ جانتا ہے۔"""
),
779: (
"جب اللہ نے فرمایا — اے عیسیٰ ابنِ مریم! یاد کرو میری — نعمت — تم پر — اور تمہاری ماں پر — جب میں نے تمہیں روح القدس سے — تائید کی — تم لوگوں سے — پیدائش کے وقت — اور جوانی میں — کلام کرتے تھے — اور جب میں نے تمہیں کتاب، حکمت، تورات اور انجیل — سکھائی — اور جب تم — مٹی — سے — پرندہ کی شکل کا — بناتے تھے — میری اجازت سے — پھر تم اس میں پھونکتے تھے — تو وہ میری اجازت سے پرندہ بن جاتا تھا — اور تم — مادر زاد اندھے اور برص والے کو — میری اجازت سے — ٹھیک کرتے تھے — اور جب تم — مردہ لوگوں کو — میری اجازت سے زندہ کرتے تھے — اور جب میں نے — بنی اسرائیل کو — تم سے — روک دیا تھا — جب تم ان کے پاس کھلی دلیلیں لائے — تو ان میں سے جو کافر ہوئے انہوں نے کہا — یہ تو کھلا جادو ہے",
"""۱۔ عیسیٰؑ پر اللہ کے انعامات — کئی معجزات۔
۲۔ ’’إِذْ قَالَ اللّٰہُ يَا عِيسَى ابْنَ مَرْيَمَ اذْكُرْ نِعْمَتِي عَلَيْكَ وَعَلَىٰ وَالِدَتِكَ‘‘ — جب اللہ نے فرمایا — اے عیسیٰ ابنِ مریم! یاد کرو میری — نعمت — تم پر — اور تمہاری ماں پر — یعنی عیسیٰؑ اور ان کی والدہ مریمؑ پر اللہ کا احسان۔
۳۔ ’’إِذْ أَيَّدتُّكَ بِرُوحِ الْقُدُسِ تُكَلِّمُ النَّاسَ فِي الْمَهْدِ وَكَهْلًا‘‘ — جب میں نے تمہیں روح القدس سے — تائید کی — تم لوگوں سے — پیدائش کے وقت — اور جوانی میں — کلام کرتے تھے — یعنی پنگوڑے میں بھی کلام — یہ معجزہ تھا۔
۴۔ ’’وَإِذْ عَلَّمْتُكَ الْكِتَابَ وَالْحِكْمَۃَ وَالتَّوْرَاةَ وَالْإِنجِيلَ‘‘ — اور جب میں نے تمہیں کتاب، حکمت، تورات اور انجیل — سکھائی۔
۵۔ ’’وَإِذْ تَخْلُقُ مِنَ الطِّينِ كَهَيْئَۃِ الطَّيْرِ بِإِذْنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيْرًا بِإِذْنِي‘‘ — اور جب تم — مٹی — سے — پرندہ کی شکل کا — بناتے تھے — میری اجازت سے — پھر تم اس میں پھونکتے تھے — تو وہ میری اجازت سے پرندہ بن جاتا تھا — یعنی اللہ کے حکم سے — مٹی سے پرندہ بننا — عیسیٰؑ کا معجزہ۔
۶۔ ’’وَتُبْرِئُ الْأَكْمَهَ وَالْأَبْرَصَ بِإِذْنِي وَإِذْ تُخْرِجُ الْمَوْتَىٰ بِإِذْنِي‘‘ — اور تم — مادر زاد اندھے اور برص والے کو — میری اجازت سے — ٹھیک کرتے تھے — اور جب تم — مردہ لوگوں کو — میری اجازت سے زندہ کرتے تھے — یعنی — مادر زاد اندھا اور برص والا — اور مردہ — سب اللہ کے حکم سے ٹھیک ہوئے۔
۷۔ ’’وَإِذْ كَفَفْتُ بَنِي إِسْرَائِيلَ عَنكَ إِذْ جِئْتَهُم بِالْبَيِّنَاتِ فَقَالَ الَّذِينَ كَفَرُوا مِنْهُمْ إِنْ هَٰذَا إِلَّا سِحْرٌ مُّبِينٌ‘‘ — اور جب میں نے — بنی اسرائیل کو — تم سے — روک دیا تھا — جب تم ان کے پاس کھلی دلیلیں لائے — تو ان میں سے جو کافر ہوئے انہوں نے کہا — یہ تو کھلا جادو ہے — یعنی بنی اسرائیل نے معجزات دیکھ کر بھی ایمان نہیں لائے۔
۸۔ عملی سبق: عیسیٰؑ اللہ کے رسول ہیں — اللہ کے حکم سے معجزات دکھائے؛ انہیں خدا نہ مانو۔"""
),
}
